"2026-07-24T11:14:02-04:00\",\"message\":\"TRUNK-6712: Cache flattened role privileges for privilege and superuser checks (#6383)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"265582974b2589ffc8787b57c2e4ba0368cb6cba\",\"date\":\"2026-07-21T12:44:21-04:00\",\"message\":\"TRUNK-6713: Follow-up: Comment clean-up\",\"refs\":\"\",\"body\":\"This was already included in the backports\\n\",\"authorName\":\"Ian\",\"authorEmail\":\"ian.c.bacher@gmail.com\"},{\"hash\":\"b68355b3dd934c7d5be3708d6637dfae8f845ee5\",\"date\":\"2026-07-21T11:26:59-04:00\",\"message\":\"TRUNK-6713: Switch to saner DaemonThread protection scheme (#6349)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Ian\",\"authorEmail\":\"52504170+ibacher@users.noreply.github.com\"},{\"hash\":\"84963803c794accceb19cf2236b859c747371336\",\"date\":\"2026-07-01T13:43:53+02:00\",\"message\":\"Fix @since 2.9.x to 2.9.0\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"rkorytkowski\",\"authorEmail\":\"rafal.korytkowski@gmail.com\"}],\"totalCount\":8}"}],"tool_result_meta":[{"id":"toolu_01V4YjnnwD1ypDj75MdhX91U","permission_decision":{"decision":"accept","source":"config","reason_type":"rule"}}]}
